const sharp = require('sharp');
const fs = require('fs');
const path = require('path');

const inputPath = path.join(__dirname, 'assets', 'Ammar-P.P1x1-B.jpeg');
const publicDir = path.join(__dirname, 'public');
const appDir = path.join(__dirname, 'src', 'app');

async function processImages() {
    try {
        console.log('Processing images...');

        // 1. Create Circular Icon for browser favicon/icon
        // Note: Actual favicons are usually square files that the browser masks, 
        // but to "force" a round look in contexts that support transparency (like tabs), 
        // we make a PNG with transparent corners.
        const circleBuffer = await sharp(inputPath)
            .resize(256, 256)
            .composite([{
                input: Buffer.from(
                    `<svg><circle cx="128" cy="128" r="128" fill="black"/></svg>`
                ),
                blend: 'dest-in'
            }])
            .png()
            .toBuffer();

        // Save as icon.png (Next.js automatically handles this for favicons if placed in src/app)
        // We use .png to support transparency for the circular cut
        fs.writeFileSync(path.join(appDir, 'icon.png'), circleBuffer);

        // Also save to public for good measure/backwards compatibility
        fs.writeFileSync(path.join(publicDir, 'favicon.png'), circleBuffer);

        console.log('Created circular icons (icon.png, favicon.png)');

        // 2. Rectangular (Original) for OpenGraph (Social Link Preview)
        // The user effectively wants the full image "Ammar-P.P1x1-B.jpeg" for social cards.
        // It is already square (P1x1), but "rectangular" in the sense of filling the frame.
        // Next.js uses opengraph-image.jpeg|png

        const originalBuffer = await sharp(inputPath)
            .toFormat('jpeg')
            .toBuffer();

        fs.writeFileSync(path.join(appDir, 'opengraph-image.jpeg'), originalBuffer);

        // Twitter image as well
        fs.writeFileSync(path.join(appDir, 'twitter-image.jpeg'), originalBuffer);

        console.log('Created rectangular OpenGraph images (opengraph-image.jpeg, twitter-image.jpeg)');

        // 3. Apple Touch Icon (usually square, but we can make it our circular version or just the standard square)
        // iOS icons usually add their own rounded corners, so standard practice is square.
        // However, if the user explicitly wants circular *everywhere*, we can try the circle version with white background or transparency.
        // Let's stick to the generated circle png for consistency with "Show browser favicon... in round form"
        fs.writeFileSync(path.join(appDir, 'apple-icon.png'), circleBuffer);
        console.log('Created apple-icon.png');

    } catch (error) {
        console.error('Error processing images:', error);
    }
}

processImages();

const fs = require('fs');
const path = require('path');

const targetDir = 'c:\\portfolio\\protfolio-main\\protfolio\\src\\components';

function replaceColorsInFile(filePath) {
    if (!filePath.endsWith('.tsx') && !filePath.endsWith('.ts')) return;

    let content = fs.readFileSync(filePath, 'utf8');

    // Replace blue with purple
    content = content.replace(/blue-(\d+)/g, 'purple-$1');
    // Replace blue-50 if not caught (though \d+ catches 50, but let's be safe)
    content = content.replace(/blue-50(?!0)/g, 'purple-50');

    // Replace cyan with fuchsia
    content = content.replace(/cyan-(\d+)/g, 'fuchsia-$1');
    content = content.replace(/cyan-50(?!0)/g, 'fuchsia-50');

    fs.writeFileSync(filePath, content, 'utf8');
}

function processDirectory(dirPath) {
    const entries = fs.readdirSync(dirPath, { withFileTypes: true });
    for (const entry of entries) {
        const fullPath = path.join(dirPath, entry.name);
        if (entry.isDirectory()) {
            processDirectory(fullPath);
        } else {
            replaceColorsInFile(fullPath);
        }
    }
}

processDirectory(targetDir);
console.log('Colors replaced successfully!');

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { cn } from "@/lib/utils";
import { Menu, X } from "lucide-react";
import { motion } from "framer-motion";
import { ThemeToggle } from "./ThemeToggle";
import { BASE_PATH } from "@/lib/constants";

const navLinks = [
    { name: "About", href: "#about" },
    { name: "Leadership", href: "#leadership" },
    { name: "Public Health", href: "#public-health" },
    { name: "Occupation", href: "#experience" },
    { name: "Credentials", href: "#education" },
    { name: "Academic", href: "#academic" },
    { name: "International", href: "#international" },
    { name: "Objectives", href: "#objectives" },
    { name: "Contact", href: "#contact" },
];

export function Header() {
    const [isScrolled, setIsScrolled] = useState(false);
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

    useEffect(() => {
        const handleScroll = () => {
            setIsScrolled(window.scrollY > 50);
        };
        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    return (
        <header
            className={cn(
                "fixed top-0 left-0 right-0 z-50 transition-all duration-300",
                isScrolled
                    ? "bg-white/80 dark:bg-black/80 backdrop-blur-md shadow-sm py-4"
                    : "bg-transparent py-6"
            )}
        >
            <div className="container mx-auto px-6 md:px-4 flex justify-between items-center">
                <Link href="/" className="flex items-center gap-3">
                    <div className="relative w-9 h-9 sm:w-10 sm:h-10 rounded-full overflow-hidden border border-gray-200 dark:border-gray-800 shadow-sm flex-shrink-0">
                        <img
                            src={`${BASE_PATH}/Ammar-P.P1x1-B.jpeg`}
                            alt="Ammar"
                            className="w-full h-full object-cover"
                        />
                    </div>
                    <span className="text-lg sm:text-xl font-bold tracking-tight">Ammar</span>
                </Link>

                {/* Desktop Nav */}
                <nav className="hidden md:flex gap-8 items-center">
                    {navLinks.map((link) => (
                        <Link
                            key={link.name}
                            href={link.href}
                            className="text-sm font-medium hover:text-purple-600 transition-colors"
                        >
                            {link.name}
                        </Link>
                    ))}
                    <ThemeToggle />
                    <Link
                        href="#contact"
                        className="px-4 py-2 bg-purple-600 text-white rounded-full text-sm font-medium hover:bg-purple-700 transition w-fit"
                    >
                        Let's Talk
                    </Link>
                </nav>

                {/* Mobile Toggle & Theme */}
                <div className="flex items-center gap-4 md:hidden">
                    <ThemeToggle />
                    <button
                        onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                        aria-label="Toggle menu"
                    >
                        {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
                    </button>
                </div>
            </div>

            {/* Mobile Nav */}
            {isMobileMenuOpen && (
                <motion.div
                    initial={{ opacity: 0, y: -20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -20 }}
                    className="absolute top-full left-0 right-0 bg-white dark:bg-black border-t border-gray-200 dark:border-gray-800 p-4 md:hidden flex flex-col gap-4 shadow-lg max-h-[85vh] overflow-y-auto"
                >
                    {navLinks.map((link) => (
                        <Link
                            key={link.name}
                            href={link.href}
                            className="text-lg font-medium"
                            onClick={() => setIsMobileMenuOpen(false)}
                        >
                            {link.name}
                        </Link>
                    ))}
                </motion.div>
            )}
        </header>
    );
}

"use client"

import { Moon, Sun } from "lucide-react"
import { useTheme } from "next-themes"
import { useEffect, useState } from "react"

export function ThemeToggle() {
    const { theme, setTheme } = useTheme()
    const [mounted, setMounted] = useState(false)

    // Avoid hydration mismatch
    useEffect(() => {
        setMounted(true)
    }, [])

    if (!mounted) return <div className="w-9 h-9" /> // Placeholder to prevent layout shift

    return (
        <button
            onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
            className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors relative focus:outline-hidden"
            aria-label="Toggle theme"
        >
            <div className="relative w-5 h-5">
                <Sun
                    className="absolute inset-0 rotate-0 scale-100 transition-all duration-300 dark:-rotate-90 dark:scale-0 text-amber-500"
                    size={20}
                />
                <Moon
                    className="absolute inset-0 rotate-90 scale-0 transition-all duration-300 dark:rotate-0 dark:scale-100 text-purple-400"
                    size={20}
                />
            </div>
        </button>
    )
}

"use client";

import { useEffect, useRef, useState } from "react";
import Script from "next/script";

declare global {
    interface Window {
        VANTA: any;
        THREE: any;
    }
}

export function VantaBackground({ children }: { children: React.ReactNode }) {
    const vantaRef = useRef<HTMLDivElement>(null);
    const [vantaEffect, setVantaEffect] = useState<any>(null);
    const [scriptsLoaded, setScriptsLoaded] = useState({ three: false, vanta: false });

    // Debug script loading
    useEffect(() => {
        if (scriptsLoaded.three && scriptsLoaded.vanta) {
            console.log("Scripts loaded, initializing Vanta...");
        }
    }, [scriptsLoaded]);

    useEffect(() => {
        if (scriptsLoaded.three && scriptsLoaded.vanta && !vantaEffect && vantaRef.current) {
            try {
                const effect = window.VANTA.CLOUDS({
                    el: vantaRef.current,
                    THREE: window.THREE, // Explicitly pass THREE to Vanta
                    mouseControls: true,
                    touchControls: true,
                    gyroControls: false,
                    minHeight: 200.00,
                    minWidth: 200.00,
                    skyColor: 0x15092a,
                    cloudColor: 0x2a1154,
                    cloudShadowColor: 0x090214,
                    sunColor: 0xa855f7,
                    sunGlareColor: 0xc084fc,
                    sunlightColor: 0x9333ea,
                });
                setVantaEffect(effect);
            } catch (error) {
                console.error("Failed to initialize Vanta:", error);
            }
        }
        return () => {
            if (vantaEffect) vantaEffect.destroy();
        };
    }, [scriptsLoaded, vantaEffect]);

    return (
        <>
            <Script
                src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r134/three.min.js"
                strategy="lazyOnload"
                onLoad={() => {
                    console.log("Three.js loaded");
                    setScriptsLoaded(prev => ({ ...prev, three: true }));
                }}
            />
            <Script
                src="https://cdn.jsdelivr.net/npm/vanta@0.5.24/dist/vanta.clouds.min.js"
                strategy="lazyOnload"
                onLoad={() => {
                    console.log("Vanta loaded");
                    setScriptsLoaded(prev => ({ ...prev, vanta: true }));
                }}
            />

            <div ref={vantaRef} className="fixed inset-0 -z-50 w-full h-full bg-gray-50 dark:bg-black pointer-events-none">
                {children}
            </div>
        </>
    );
}

