                </motion.div>

                {/* Grid Container */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 auto-rows-fr">
                    {portfolioData.publicHealth.map((project, index) => (
                        <PublicHealthCard
                            key={index}
                            project={project}
                            index={index}
                            onOpen={(tab) => openModal(project, tab)}
